class Solution:
    def countIndicesWithOppositeParity(self, nums):
        n = len(nums)
        ans = [0] * n
        for i in range(n):
            for j in range(i + 1, n):
                if nums[i] % 2 != nums[j] % 2:
                    ans[i] += 1
        return ans

