        int n = nums.size();
        vector<int> ans(n);
        long long even = 0, odd = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (nums[i] % 2 == 0) { ans[i] = odd; even++; }
            else { ans[i] = even; odd++; }
        }
        return ans;
    }
};

